@Override public String getPassword(final Scheme scheme,final int port,final String hostname,final String user){
  try {
    final List<String> list=keyring.getItems(this.createAttributes(String.format("%s://%s@%s:%d",scheme,user,hostname,port)));
    if (list != null && !list.isEmpty()) {
      return String.valueOf(keyring.getSecret(list.get(0)));
    }
    else {
      return null;
    }
  } catch (IllegalFormatException | IndexOutOfBoundsException e) {
    return null;
  }
}
